WITH return_metrics AS ( SELECT t.t_hour, ca_ret.ca_city AS returning_city, ca_ref.ca_city AS refunded_city, SUM(wr.wr_return_amt_inc_tax) AS total_return_amount, SUM(wr.wr_net_loss) AS total_net_loss, AVG(wr.wr_return_quantity) AS avg_return_quantity, COUNT(*) AS return_cnt, SUM(wr.wr_refunded_cash) AS total_refunded_cash, SUM(wr.wr_refunded_cash) / NULLIF(SUM(wr.wr_return_amt_inc_tax), 0) AS refund_to_return_ratio FROM web_returns wr JOIN time_dim t ON wr.wr_returned_time_sk = t.t_time_sk JOIN customer_address ca_ret ON wr.wr_returning_addr_sk = ca_ret.ca_address_sk JOIN customer_address ca_ref ON wr.wr_refunded_addr_sk = ca_ref.ca_address_sk WHERE t.t_hour BETWEEN 9 AND 17 AND ca_ret.ca_state = 'CA' GROUP BY t.t_hour, ca_ret.ca_city, ca_ref.ca_city ) SELECT t_hour, returning_city, refunded_city, total_return_amount, total_net_loss, avg_return_quantity, return_cnt, total_refunded_cash, refund_to_return_ratio, RANK() OVER (PARTITION BY t_hour ORDER BY total_return_amount DESC) AS city_return_rank FROM return_metrics ORDER BY t_hour, city_return_rank
